def select_model():
    """Let user select a model."""
    print("\n" + "="*60)
    print("AVAILABLE CODING MODELS")
    print("="*60)
    
    for key, info in MODEL_OPTIONS.items():
        print(f"\n[{key.upper()}] {info['name']}")
        print(f"    Size: {info['size']} parameters")
        print(f"    Disk: ~{info['disk_space']}")
        print(f"    Desc: {info['description']}")
    
    print("\n" + "="*60)
    
    while True:
        choice = input("\nSelect model (tiny/small/medium/python/instruct/multilang) or enter custom HuggingFace ID: ").strip().lower()
        
        if choice in MODEL_OPTIONS:
            return MODEL_OPTIONS[choice]['name']
        elif choice and '/' in choice:  # Looks like a HuggingFace ID
            print(f"\nUsing custom model: {choice}")
            print("Warning: Ensure this is a text generation model compatible with transformers.")
            return choice
        else:
            print("Invalid choice. Please select from the options or enter a HuggingFace model ID.")

def check_and_install_dependencies():
    """Check and install required packages."""
    print("\nChecking dependencies...")
    
    # Base requirements
    base_packages = [
        'transformers>=4.30.0',
        'torch>=2.0.0',
        'accelerate>=0.20.0',
        'sentencepiece',
        'protobuf',
        'psutil',
        'tqdm',
        'requests'
    ]
    
    for package in base_packages:
        package_name = package.split('>')[0].split('<')[0].split('=')[0]
        try:
            __import__(package_name.replace('-', '_'))
            print(f"✓ {package_name}")
        except ImportError:
            print(f"Installing {package_name}...")
            subprocess.check_call([sys.executable, "-m", "pip", "install", package, "--quiet"])
    
    print("✓ All dependencies installed")

def download_model(model_name):
    """Download the selected model."""
    try:
        from transformers import AutoTokenizer, AutoModelForCausalLM
        import torch
        
        print(f"\nDownloading: {model_name}")
        print("This may take a few minutes depending on model size...")
        
        # Configure model loading
        torch_dtype = torch.float16 if torch.cuda.is_available() else torch.float32
        
        # Special handling for some models
        if "codegen" in model_name.lower():
            # CodeGen models work well with standard loading
            tokenizer = AutoTokenizer.from_pretrained(model_name)
            model = AutoModelForCausalLM.from_pretrained(
                model_name,
                torch_dtype=torch_dtype,
                low_cpu_mem_usage=True,
                trust_remote_code=True
            )
        elif "starcoder" in model_name.lower():
            # StarCoder models need special tokens
            tokenizer = AutoTokenizer.from_pretrained(model_name)
            model = AutoModelForCausalLM.from_pretrained(
                model_name,
                torch_dtype=torch_dtype,
                low_cpu_mem_usage=True,
                trust_remote_code=True
            )
            tokenizer.pad_token = tokenizer.eos_token
        elif "deepseek" in model_name.lower():
            # DeepSeek models
            tokenizer = AutoTokenizer.from_pretrained(model_name)
            model = AutoModelForCausalLM.from_pretrained(
                model_name,
                torch_dtype=torch_dtype,
                low_cpu_mem_usage=True,
                trust_remote_code=True
            )
        else:
            # Generic loading
            tokenizer = AutoTokenizer.from_pretrained(model_name)
            model = AutoModelForCausalLM.from_pretrained(
                model_name,
                torch_dtype=torch_dtype,
                low_cpu_mem_usage=True
            )
        
        # Set pad token if not set
        if tokenizer.pad_token is None:
            tokenizer.pad_token = tokenizer.eos_token
        
        # Move to GPU if available
        device = "cuda" if torch.cuda.is_available() else "cpu"
        model = model.to(device)
        
        print(f"✓ Model loaded on {device}")
        print(f"  Model size: {sum(p.numel() for p in model.parameters()):,} parameters")
        
        return model, tokenizer, device
        
    except Exception as e:
        print(f"\n❌ Error loading model: {e}")
        print("\nTrying alternative approach...")
        
        # Try with simpler loading
        try:
            from transformers import AutoTokenizer, AutoModelForCausalLM
            import torch
            
            tokenizer = AutoTokenizer.from_pretrained(model_name)
            model = AutoModelForCausalLM.from_pretrained(
                model_name,
                torch_dtype=torch.float32,
                device_map="auto" if torch.cuda.is_available() else None
            )
            
            device = "cuda" if torch.cuda.is_available() else "cpu"
            print(f"✓ Model loaded with simpler approach")
            return model, tokenizer, device
            
        except Exception as e2:
            print(f"❌ Failed to load model: {e2}")
            print("\nContinuing without AI model...")
            return None, None, None

def analyze_project(project_path):
    """Analyze Python project structure."""
    project_path = Path(project_path)
    
    if not project_path.exists():
        raise FileNotFoundError(f"Project path not found: {project_path}")
    
    print(f"\nAnalyzing: {project_path}")
    
    project_info = {
        'name': project_path.name,
        'path': str(project_path),
        'files': [],
        'imports': set(),
        'functions': [],
        'classes': [],
        'entry_points': [],
        'total_lines': 0
    }
    
    # Find all Python files
    python_files = list(project_path.rglob("*.py"))
    
    if not python_files:
        print("No Python files found!")
        return project_info
    
    print(f"Found {len(python_files)} Python files")
    
    for py_file in python_files:
        if '__pycache__' in str(py_file) or '.pyc' in str(py_file):
            continue
            
        rel_path = py_file.relative_to(project_path)
        
        try:
            with open(py_file, 'r', encoding='utf-8', errors='ignore') as f:
                content = f.read()
            
            lines = content.splitlines()
            project_info['total_lines'] += len(lines)
            
            # Simple analysis
            file_imports = extract_imports(content)
            file_functions = extract_functions(content)
            file_classes = extract_classes(content)
            
            project_info['imports'].update(file_imports)
            project_info['functions'].extend([f"{rel_path}:{f}" for f in file_functions])
            project_info['classes'].extend([f"{rel_path}:{c}" for c in file_classes])
            
            if '__main__' in content and 'if __name__' in content:
                project_info['entry_points'].append(str(rel_path))
            
            project_info['files'].append({
                'path': str(py_file),
                'relative': str(rel_path),
                'lines': len(lines),
                'imports': list(file_imports),
                'functions': file_functions,
                'classes': file_classes
            })
            
        except Exception as e:
            print(f"  Warning: Could not read {rel_path}: {e}")
    
    print(f"  Total lines: {project_info['total_lines']}")
    print(f"  Unique imports: {len(project_info['imports'])}")
    print(f"  Functions: {len(project_info['functions'])}")
    print(f"  Classes: {len(project_info['classes'])}")
    print(f"  Entry points: {len(project_info['entry_points'])}")
    
    return project_info

def extract_imports(content):
    """Extract import statements."""
    imports = set()
    for line in content.splitlines():
        line = line.strip()
        if line.startswith(('import ', 'from ')):
            # Remove comments
            line = line.split('#')[0].strip()
            if line:
                imports.add(line)
    return imports

def extract_functions(content):
    """Extract function definitions."""
    functions = []
    for line in content.splitlines():
        line = line.strip()
        if line.startswith('def '):
            match = re.match(r'def\s+(\w+)\s*\(', line)
            if match:
                functions.append(match.group(1))
    return functions

def extract_classes(content):
    """Extract class definitions."""
    classes = []
    for line in content.splitlines():
        line = line.strip()
        if line.startswith('class '):
            match = re.match(r'class\s+(\w+)', line)
            if match:
                classes.append(match.group(1))
    return classes

def merge_with_ai(project_info, model, tokenizer, output_path):
    """Use AI to help merge and organize code."""
    print("\nUsing AI to optimize merge...")
    
    try:
        import torch
        
        # Create context for AI
        context = f"""
        Project: {project_info['name']}
        Files: {len(project_info['files'])}
        Total lines: {project_info['total_lines']}
        Imports: {', '.join(sorted(project_info['imports'])[:20])}
        
        I need to merge all these Python files into one well-organized file.
        The merged file should:
        1. Group related functionality together
        2. Remove duplicate imports
        3. Preserve all functionality
        4. Have clear organization
        
        Suggest the best structure for the merged file:
        """
        
        inputs = tokenizer(context, return_tensors="pt", truncation=True, max_length=512)
        inputs = inputs.to(model.device)
        
        # Generate suggestions
        with torch.no_grad():
            outputs = model.generate(
                **inputs,
                max_new_tokens=500,
                temperature=0.7,
                do_sample=True,
                pad_token_id=tokenizer.pad_token_id or tokenizer.eos_token_id
            )
        
        suggestions = tokenizer.decode(outputs[0], skip_special_tokens=True)
        
        # Extract AI suggestions
        ai_suggestions = suggestions.split("Suggest the best structure")[-1].strip()
        
        print("\nAI Suggestions:")
        print("-" * 40)
        print(ai_suggestions[:500] + "..." if len(ai_suggestions) > 500 else ai_suggestions)
        print("-" * 40)
        
        return ai_suggestions
        
    except Exception as e:
        print(f"AI generation failed: {e}")
        return None

def create_merged_file(project_info, ai_suggestions, output_path):
    """Create the final merged file."""
    print(f"\nCreating merged file: {output_path}")
    
    merged = []
    
    # Header
    merged.append(f'# {"="*60}')
    merged.append(f'# MERGED: {project_info["name"]}')
    merged.append(f'# Generated from {len(project_info["files"])} files')
    merged.append(f'# Total source lines: {project_info["total_lines"]}')
    merged.append(f'# {"="*60}\n')
    
    # AI suggestions if available
    if ai_suggestions:
        merged.append('# AI SUGGESTED STRUCTURE:')
        merged.append('# ' + '-'*40)
        for line in ai_suggestions.split('\n'):
            if line.strip():
                merged.append(f'# {line}')
        merged.append('# ' + '-'*40 + '\n')
    
    # Imports section
    merged.append('# IMPORTS')
    merged.append('# ' + '='*40)
    
    imports = sorted(project_info['imports'])
    if imports:
        for imp in imports:
            merged.append(imp)
    else:
        merged.append('# No imports found')
    
    merged.append('')
    
    # File contents
    merged.append('# SOURCE CODE')
    merged.append('# ' + '='*40)
    
    for file_info in project_info['files']:
        merged.append(f'\n# {"-"*40}')
        merged.append(f'# FILE: {file_info["relative"]}')
        merged.append(f'# Lines: {file_info["lines"]}')
        
        if file_info['functions']:
            merged.append(f'# Functions: {", ".join(file_info["functions"])}')
        
        if file_info['classes']:
            merged.append(f'# Classes: {", ".join(file_info["classes"])}')
        
        merged.append(f'# {"-"*40}\n')
        
        try:
            with open(file_info['path'], 'r', encoding='utf-8', errors='ignore') as f:
                content = f.read()
            merged.append(content)
        except:
            merged.append(f'# Could not read file content')
    
    # Footer
    merged.append('\n' + '# ' + '='*40)
    merged.append('# END OF MERGED FILE')
    merged.append('# ' + '='*40)
    
    # Write file
    with open(output_path, 'w', encoding='utf-8') as f:
        f.write('\n'.join(merged))
    
    print(f"✓ Created {output_path}")
    print(f"  Total lines in merged file: {len(merged)}")
    
    # Save project info as JSON
    info_path = output_path.replace('.py', '_info.json')
    with open(info_path, 'w', encoding='utf-8') as f:
        json.dump({
            'project_name': project_info['name'],
            'files_merged': len(project_info['files']),
            'total_source_lines': project_info['total_lines'],
            'unique_imports': len(project_info['imports']),
            'total_functions': len(project_info['functions']),
            'total_classes': len(project_info['classes']),
            'entry_points': project_info['entry_points'],
            'ai_suggestions': ai_suggestions[:1000] if ai_suggestions else None
        }, f, indent=2)
    
    print(f"✓ Project info saved to {info_path}")

def main():
    """Main function."""
    print("\n" + "="*60)
    print("AI-POWERED CODE MERGER")
    print("="*60)
    
    parser = argparse.ArgumentParser(description='Merge Python projects with AI assistance')
    parser.add_argument('--project', '-p', default='Project/merge',
                       help='Path to project folder')
    parser.add_argument('--output', '-o', default='merged_output.py',
                       help='Output filename')
    parser.add_argument('--model', '-m', 
                       help='HuggingFace model ID (optional)')
    parser.add_argument('--no-ai', action='store_true',
                       help='Skip AI model download')
    
    args = parser.parse_args()
    
    # Install dependencies
    check_and_install_dependencies()
    
    # Select model
    model_name = args.model
    if not model_name and not args.no_ai:
        model_name = select_model()
    
    # Download model (if not skipped)
    model = tokenizer = device = None
    ai_suggestions = None
    
    if model_name and not args.no_ai:
        model, tokenizer, device = download_model(model_name)
    
    # Analyze project
    try:
        project_info = analyze_project(args.project)
    except FileNotFoundError as e:
        print(f"\n❌ Error: {e}")
        print(f"Please check that the folder exists: {args.project}")
        return
    
    if not project_info['files']:
        print("\n❌ No Python files found to merge.")
        return
    
    # Get AI suggestions if model loaded
    if model and tokenizer:
        ai_suggestions = merge_with_ai(project_info, model, tokenizer, args.output)
    
    # Create merged file
    create_merged_file(project_info, ai_suggestions, args.output)
    
    # Final message
    print("\n" + "="*60)
    print("MERGE COMPLETE!")
    print("="*60)
    print(f"\n📁 Input: {args.project}")
    print(f"📄 Output: {args.output}")
    print(f"🤖 AI Used: {'Yes' if ai_suggestions else 'No'}")
    print(f"📊 Files merged: {len(project_info['files'])}")
    print(f"📝 Source lines: {project_info['total_lines']}")
    
    # Quick syntax check
    print("\n🔍 Running syntax check...")
    try:
        result = subprocess.run(
            [sys.executable, "-m", "py_compile", args.output],
            capture_output=True,
            text=True,
            timeout=5
        )
        if result.returncode == 0:
            print("✅ Syntax check passed!")
        else:
            print("⚠️  Syntax errors found (common in merged files)")
            print("   You may need to fix import conflicts.")
    except:
        print("⚠️  Could not run syntax check")
    
    print("\n🎯 Next steps:")
    print("1. Review the merged file")
    print("2. Test the functionality")
    print("3. Remove any duplicate code")
    print("4. Organize imports if needed")

if __name__ == "__main__":
    main()

