def check_and_install_dependencies():
    """Check and install required Python packages."""
    required_packages = [
        'transformers',
        'torch',
        'accelerate',
        'sentencepiece',
        'protobuf',
        'psutil',
        'tqdm'
    ]
    
    print("Checking dependencies...")
    for package in required_packages:
        try:
            __import__(package.replace('-', '_'))
            print(f"✓ {package}")
        except ImportError:
            print(f"Installing {package}...")
            subprocess.check_call([sys.executable, "-m", "pip", "install", package])
            print(f"✓ {package} installed")

def download_model():
    """
    Download a small, efficient coding LLM.
    Using CodeGen-350M-mono as it's good for code generation and small enough.
    """
    from transformers import AutoTokenizer, AutoModelForCausalLM
    import torch
    
    model_name = "Salesforce/codegen-350M-mono"  # 350M parameters, good for code
    # Alternative options (uncomment if you want a different model):
    # model_name = "microsoft/CodeGPT-small-py"  # 125M parameters, Python-specific
    # model_name = "facebook/incoder-1B"  # 1B parameters, good for infilling
    
    print(f"Downloading model: {model_name}")
    print("This may take a few minutes (350MB download)...")
    
    try:
        # Download tokenizer and model
        tokenizer = AutoTokenizer.from_pretrained(model_name)
        model = AutoModelForCausalLM.from_pretrained(
            model_name,
            torch_dtype=torch.float16 if torch.cuda.is_available() else torch.float32,
            low_cpu_mem_usage=True
        )
        
        # Move to GPU if available
        device = "cuda" if torch.cuda.is_available() else "cpu"
        model = model.to(device)
        
        print(f"Model loaded successfully on {device}")
        return model, tokenizer, device
        
    except Exception as e:
        print(f"Error downloading model: {e}")
        print("Falling back to local model analysis only...")
        return None, None, None

def analyze_project_structure(project_path: str) -> Dict:
    """Analyze the project structure and extract information."""
    project_path = Path(project_path)
    
    if not project_path.exists():
        print(f"Error: Project path '{project_path}' does not exist")
        return {}
    
    print(f"Analyzing project structure in: {project_path}")
    
    project_info = {
        'path': str(project_path),
        'files': [],
        'imports': set(),
        'classes': [],
        'functions': [],
        'dependencies': set(),
        'entry_points': []
    }
    
    # Common Python file patterns
    python_patterns = ['*.py', '*.pyx', '*.pxd']
    
    for pattern in python_patterns:
        for py_file in project_path.rglob(pattern):
            if '__pycache__' in str(py_file) or '.pyc' in str(py_file):
                continue
                
            rel_path = py_file.relative_to(project_path)
            
            file_info = {
                'path': str(py_file),
                'relative_path': str(rel_path),
                'size': py_file.stat().st_size,
                'content_hash': hashlib.md5(py_file.read_bytes()).hexdigest()[:8]
            }
            
            # Read and analyze file content
            try:
                content = py_file.read_text(encoding='utf-8', errors='ignore')
                file_info['lines'] = len(content.splitlines())
                
                # Extract basic info without AST (to avoid syntax errors)
                imports = extract_imports_simple(content)
                functions = extract_functions_simple(content)
                classes = extract_classes_simple(content)
                
                file_info['imports'] = imports
                file_info['functions'] = functions
                file_info['classes'] = classes
                
                # Update project info
                project_info['imports'].update(imports)
                project_info['functions'].extend([f"{rel_path}:{f}" for f in functions])
                project_info['classes'].extend([f"{rel_path}:{c}" for c in classes])
                
                # Check for entry points
                if '__main__' in content and 'if __name__' in content:
                    project_info['entry_points'].append(str(rel_path))
                    
            except Exception as e:
                print(f"Warning: Could not analyze {rel_path}: {e}")
                file_info['error'] = str(e)
            
            project_info['files'].append(file_info)
    
    print(f"Found {len(project_info['files'])} Python files")
    print(f"Found {len(project_info['imports'])} unique imports")
    print(f"Found {len(project_info['functions'])} functions")
    print(f"Found {len(project_info['classes'])} classes")
    
    return project_info

def extract_imports_simple(content: str) -> Set[str]:
    """Simple import extraction without AST."""
    imports = set()
    lines = content.splitlines()
    
    for line in lines:
        line = line.strip()
        if line.startswith('import ') or line.startswith('from '):
            # Clean up the import line
            import_line = line.split('#')[0].strip()  # Remove comments
            if import_line:
                imports.add(import_line)
    
    return imports

def extract_functions_simple(content: str) -> List[str]:
    """Simple function extraction without AST."""
    functions = []
    lines = content.splitlines()
    
    for line in lines:
        line = line.strip()
        if line.startswith('def '):
            # Extract function name
            func_match = re.match(r'def\s+(\w+)\s*\(', line)
            if func_match:
                functions.append(func_match.group(1))
    
    return functions

def extract_classes_simple(content: str) -> List[str]:
    """Simple class extraction without AST."""
    classes = []
    lines = content.splitlines()
    
    for line in lines:
        line = line.strip()
        if line.startswith('class '):
            # Extract class name
            class_match = re.match(r'class\s+(\w+)', line)
            if class_match:
                classes.append(class_match.group(1))
    
    return classes

def generate_merge_plan(project_info: Dict, model=None, tokenizer=None) -> Dict:
    """Generate a plan for merging the project files."""
    
    print("\nGenerating merge plan...")
    
    # Create a simple merge plan based on analysis
    merge_plan = {
        'project_name': Path(project_info['path']).name,
        'files_to_merge': len(project_info['files']),
        'structure': [],
        'imports': sorted(list(project_info['imports'])),
        'entry_points': project_info['entry_points'],
        'suggested_organization': []
    }
    
    # Group files by directory
    files_by_dir = {}
    for file_info in project_info['files']:
        rel_path = Path(file_info['relative_path'])
        directory = str(rel_path.parent)
        if directory == '.':
            directory = 'root'
        
        if directory not in files_by_dir:
            files_by_dir[directory] = []
        
        files_by_dir[directory].append({
            'name': rel_path.name,
            'functions': file_info.get('functions', []),
            'classes': file_info.get('classes', []),
            'lines': file_info.get('lines', 0)
        })
    
    # Create structure
    for directory, files in files_by_dir.items():
        merge_plan['structure'].append({
            'directory': directory,
            'file_count': len(files),
            'total_lines': sum(f.get('lines', 0) for f in files),
            'files': files
        })
    
    # Generate suggested organization using LLM if available
    if model and tokenizer:
        try:
            prompt = f"""Analyze this Python project structure and suggest how to merge it into a single well-organized file:

Project: {merge_plan['project_name']}
Total files: {merge_plan['files_to_merge']}
Imports needed: {', '.join(merge_plan['imports'][:10])}{'...' if len(merge_plan['imports']) > 10 else ''}

Structure:
{json.dumps(merge_plan['structure'], indent=2)}

Suggest a logical organization for a single merged Python file. Consider:
1. Import organization
2. Class and function grouping
3. Maintaining functionality
4. Entry point preservation

Suggestions:"""
            
            inputs = tokenizer(prompt, return_tensors="pt", truncation=True, max_length=512)
            inputs = inputs.to(model.device)
            
            with torch.no_grad():
                outputs = model.generate(
                    **inputs,
                    max_length=1024,
                    temperature=0.7,
                    do_sample=True,
                    pad_token_id=tokenizer.eos_token_id
                )
            
            suggestions = tokenizer.decode(outputs[0], skip_special_tokens=True)
            # Extract just the suggestions part
            if "Suggestions:" in suggestions:
                suggestions = suggestions.split("Suggestions:")[-1].strip()
            
            merge_plan['llm_suggestions'] = suggestions
            
        except Exception as e:
            print(f"LLM suggestion generation failed: {e}")
            merge_plan['llm_suggestions'] = "Could not generate LLM suggestions"
    
    # Generate default suggestions
    default_suggestions = """
1. ORGANIZE IMPORTS:
   - Standard library imports first
   - Third-party imports second
   - Local imports last
   
2. GROUP BY FUNCTIONALITY:
   - Constants and configuration
   - Utility functions
   - Core classes
   - Main functionality
   
3. PRESERVE ENTRY POINTS:
   - Keep main() functions
   - Preserve if __name__ == "__main__" blocks
   
4. REMOVE DUPLICATES:
   - Merge duplicate functions
   - Remove redundant imports
"""
    
    merge_plan['suggested_organization'] = default_suggestions
    
    return merge_plan

def merge_files_intelligently(project_info: Dict, merge_plan: Dict, output_path: str):
    """Intelligently merge project files based on the analysis."""
    
    print(f"\nMerging files to: {output_path}")
    
    # Read all file contents
    file_contents = {}
    for file_info in project_info['files']:
        try:
            with open(file_info['path'], 'r', encoding='utf-8', errors='ignore') as f:
                content = f.read()
                file_contents[file_info['relative_path']] = {
                    'content': content,
                    'lines': file_info.get('lines', 0),
                    'functions': file_info.get('functions', []),
                    'classes': file_info.get('classes', [])
                }
        except Exception as e:
            print(f"Warning: Could not read {file_info['relative_path']}: {e}")
    
    # Start building the merged file
    merged_content = []
    
    # Add header
    merged_content.append(f'# {"="*60}')
    merged_content.append(f'# MERGED PYTHON PROJECT: {merge_plan["project_name"]}')
    merged_content.append(f'# Generated from {len(file_contents)} source files')
    merged_content.append(f'# Total files analyzed: {merge_plan["files_to_merge"]}')
    merged_content.append(f'# {"="*60}\n')
    
    # Add imports section
    merged_content.append('# ' + '='*40)
    merged_content.append('# IMPORTS')
    merged_content.append('# ' + '='*40 + '\n')
    
    # Organize imports
    std_lib_imports = []
    third_party_imports = []
    local_imports = []
    
    # Common standard library modules
    std_libs = {
        'os', 'sys', 're', 'json', 'datetime', 'pathlib', 'typing',
        'collections', 'itertools', 'functools', 'math', 'random',
        'hashlib', 'subprocess', 'argparse', 'logging'
    }
    
    for imp in merge_plan['imports']:
        if any(lib in imp for lib in std_libs):
            std_lib_imports.append(imp)
        elif 'import' in imp or 'from' in imp:
            third_party_imports.append(imp)
        else:
            local_imports.append(imp)
    
    # Add standard library imports
    if std_lib_imports:
        merged_content.append('# Standard library imports')
        for imp in sorted(set(std_lib_imports)):
            merged_content.append(imp)
        merged_content.append('')
    
    # Add third-party imports
    if third_party_imports:
        merged_content.append('# Third-party imports')
        for imp in sorted(set(third_party_imports)):
            merged_content.append(imp)
        merged_content.append('')
    
    # Add file-by-file content
    merged_content.append('\n# ' + '='*40)
    merged_content.append('# MERGED CODE')
    merged_content.append('# ' + '='*40 + '\n')
    
    # Process files in a logical order
    processed_files = set()
    
    # First, process files with main/entry points
    for rel_path, info in file_contents.items():
        if any(ep in rel_path for ep in merge_plan['entry_points']):
            merged_content.append(f'\n# {"-"*40}')
            merged_content.append(f'# From: {rel_path}')
            merged_content.append(f'# Functions: {", ".join(info["functions"])}' if info["functions"] else '# No functions')
            merged_content.append(f'# Classes: {", ".join(info["classes"])}' if info["classes"] else '# No classes')
            merged_content.append(f'# {"-"*40}\n')
            merged_content.append(info['content'])
            processed_files.add(rel_path)
    
    # Then process remaining files
    for rel_path, info in file_contents.items():
        if rel_path not in processed_files:
            merged_content.append(f'\n# {"-"*40}')
            merged_content.append(f'# From: {rel_path}')
            merged_content.append(f'# Functions: {", ".join(info["functions"])}' if info["functions"] else '# No functions')
            merged_content.append(f'# Classes: {", ".join(info["classes"])}' if info["classes"] else '# No classes')
            merged_content.append(f'# {"-"*40}\n')
            merged_content.append(info['content'])
    
    # Add footer
    merged_content.append('\n' + '# ' + '='*40)
    merged_content.append('# END OF MERGED FILE')
    merged_content.append('# ' + '='*40)
    
    # Write the merged file
    with open(output_path, 'w', encoding='utf-8') as f:
        f.write('\n'.join(merged_content))
    
    print(f"Successfully merged {len(file_contents)} files")
    print(f"Total lines in merged file: {len(merged_content)}")
    
    # Also write the merge plan as JSON
    plan_path = output_path.replace('.py', '_plan.json')
    with open(plan_path, 'w', encoding='utf-8') as f:
        json.dump(merge_plan, f, indent=2)
    
    print(f"Merge plan saved to: {plan_path}")

def main():
    """Main function."""
    parser = argparse.ArgumentParser(description='Merge Python project files using AI')
    parser.add_argument('--project', '-p', default='Project/merge',
                       help='Path to project folder (default: Project/merge)')
    parser.add_argument('--output', '-o', default='merged_project.py',
                       help='Output file name (default: merged_project.py)')
    parser.add_argument('--no-model', action='store_true',
                       help='Skip downloading AI model (faster)')
    parser.add_argument('--model', default='Salesforce/codegen-350M-mono',
                       help='HuggingFace model to use')
    
    args = parser.parse_args()
    
    print("="*60)
    print("AI CODE MERGER")
    print("="*60)
    
    # Check dependencies
    check_and_install_dependencies()
    
    # Download model (optional)
    model = tokenizer = device = None
    if not args.no_model:
        try:
            # Import torch after installation
            import torch
            from transformers import AutoTokenizer, AutoModelForCausalLM
            
            print(f"\nDownloading model: {args.model}")
            tokenizer = AutoTokenizer.from_pretrained(args.model)
            model = AutoModelForCausalLM.from_pretrained(
                args.model,
                torch_dtype=torch.float16 if torch.cuda.is_available() else torch.float32,
                low_cpu_mem_usage=True
            )
            device = "cuda" if torch.cuda.is_available() else "cpu"
            model = model.to(device)
            print(f"✓ Model loaded on {device}")
        except Exception as e:
            print(f"⚠ Could not load model: {e}")
            print("Continuing with analysis only...")
    
    # Analyze project
    project_info = analyze_project_structure(args.project)
    
    if not project_info['files']:
        print("No Python files found. Exiting.")
        return
    
    # Generate merge plan
    merge_plan = generate_merge_plan(project_info, model, tokenizer)
    
    # Merge files
    merge_files_intelligently(project_info, merge_plan, args.output)
    
    print("\n" + "="*60)
    print("MERGE COMPLETE!")
    print("="*60)
    print(f"\nSummary:")
    print(f"- Input folder: {args.project}")
    print(f"- Files processed: {len(project_info['files'])}")
    print(f"- Output file: {args.output}")
    print(f"- AI Model used: {'Yes' if model else 'No'}")
    
    # Show quick stats
    import_lines = len([l for l in merge_plan['imports'] if l])
    print(f"- Unique imports: {import_lines}")
    print(f"- Functions found: {len(project_info['functions'])}")
    print(f"- Classes found: {len(project_info['classes'])}")
    
    # Check the output file
    output_path = Path(args.output)
    if output_path.exists():
        with open(output_path, 'r', encoding='utf-8') as f:
            lines = f.readlines()
        print(f"- Output file lines: {len(lines)}")
        
        # Try to run a syntax check
        print("\nRunning syntax check...")
        result = subprocess.run([sys.executable, "-m", "py_compile", args.output],
                              capture_output=True, text=True)
        if result.returncode == 0:
            print("✓ Syntax check passed!")
        else:
            print("⚠ Syntax errors found (common in merged files)")
            print("You may need to manually fix some imports or dependencies.")
    
    print("\nNext steps:")
    print("1. Review the merged file: merged_project.py")
    print("2. Check the merge plan: merged_project_plan.json")
    print("3. Test the merged code")
    print("4. Remove duplicate functions/classes if needed")

if __name__ == "__main__":
    main()

