        print(f"  Cache: {weight_info.get('weight_cache_size', 0)} weights")
        print(f"  Cache hit rate: {weight_info.get('cache_hit_rate', 0)*100:.1f}%")
        print(f"  Neural pathways: {weight_info.get('neural_pathways', 0)}")
